import urllib.request,json,datetime,subprocess
base='http://127.0.0.1:17448'
def get(p):
 with urllib.request.urlopen(base+p,timeout=6) as f:return json.load(f)
out={'time':datetime.datetime.now().isoformat(),'scope':'read_only_operational_components'}
q=get('/api/operator-lifecycle');w=get('/api/supervisor-watchdog?detect=0').get('config',{})
if not(q.get('queuePaused') is True and w.get('mode')=='off' and w.get('allowAutonomousSend') is False):raise RuntimeError('NO_SAFE_HOLD')
for key,path in [('health','/api/health'),('subsystem','/api/health/subsystems')]:
 try:
  o=get(path);v=o.get('health',o)
  out[key]={'state':v.get('state'),'reasons':v.get('reasons'),'components':{name:{k:row.get(k) for k in ('state','reason','ageMs','stale','lastCompletedAt','lastSuccessAt','consecutiveFailures','recoveredFromRestart')} for name,row in v.get('components',{}).items()},'eventLoop':v.get('eventLoop'),'queueSafety':v.get('queueSafety')}
 except Exception as e:out[key]={'error':str(e)[:90]}
print(json.dumps(out,ensure_ascii=True)[:14000])
